import struct,zlib
b=open('misc_blackboard/Blackboard.png','rb').read(); p=8; dat=b''
while p<len(b):
 n=struct.unpack('>I',b[p:p+4])[0]; typ=b[p+4:p+8]; d=b[p+8:p+8+n];p+=12+n
 if typ==b'IHDR': w,h,depth,col,_,_,inter=struct.unpack('>IIBBBBB',d)
 if typ==b'IDAT': dat+=d
raw=zlib.decompress(dat); stride=w*3; rows=[]; prev=bytearray(stride); q=0
for y in range(h):
 f=raw[q]; q+=1; cur=bytearray(raw[q:q+stride]);q+=stride
 for x in range(stride):
  a=cur[x-3] if x>=3 else 0; bb=prev[x]; c=prev[x-3] if x>=3 else 0
  if f==1: cur[x]=(cur[x]+a)&255
  elif f==2: cur[x]=(cur[x]+bb)&255
  elif f==3: cur[x]=(cur[x]+((a+bb)//2))&255
  elif f==4:
   pp=a+bb-c; pa=abs(pp-a);pb=abs(pp-bb);pc=abs(pp-c);cur[x]=(cur[x]+(a if pa<=pb and pa<=pc else bb if pb<=pc else c))&255
 rows.append(cur);prev=cur
chars=' .:-=+*#%@'
for oy in range(40,220,6):
 s=''
 for ox in range(30,1149,6):
  vals=[]
  for yy in range(oy,min(oy+6,h)):
   for xx in range(ox,min(ox+6,w)):
    r,g,b=rows[yy][xx*3:xx*3+3]; vals.append(max(r,g,b)-min(r,g,b)//4)
  v=max(vals)
  s+=chars[max(0,min(9,(v-70)*10//180))]
 print(s)
PY"

